/* Eat Lah prototype: local-first, no network or real-time store-price integration. */
(() => {
'use strict';
const D=window.EATLAH_DATA;const {ingredients:I,catalog:C,entries:E}=D;
const STORE='eat-lah-v1';
const defaultState=()=>({version:1,profileCompleted:false,profile:{nickname:'',postal:'',address:'',tools:['electric-pot','microwave'],storage:'small',budget:70,kcal:0,allergens:[],dislikes:'',skill:'new',retailer:'不限',language:'zh-en',tastes:['savory']},pantry:[],plans:[],logs:[],transactions:[],priceOverrides:{},favorites:[],purchaseHistory:[]});
let state;try{state={...defaultState(),...JSON.parse(localStorage.getItem(STORE)||'{}')}}catch(e){state=defaultState()}
state.profile={...defaultState().profile,...state.profile};if(!Array.isArray(state.profile.tastes))state.profile.tastes=['savory'];
for(const key of ['pantry','plans','logs','transactions','favorites','purchaseHistory'])if(!Array.isArray(state[key]))state[key]=[];
const ui={page:state.profileCompleted?'home':'setup',onboardStep:0,flow:null,planDays:7,cartCheck:{},cartPacks:{},showEnglish:true,pantryFilter:'all',checkSlot:'dinner',receipt:false,modal:null,setupSeasonings:[],activeMealId:null};
const app=document.getElementById('app');
function save(){try{localStorage.setItem(STORE,JSON.stringify(state))}catch(e){flash('本浏览器无法保存数据，请检查隐私设置。')}}
function id(){return Math.random().toString(36).slice(2,10)+Date.now().toString(36)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function addDay(day,n){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function dateZh(d){const x=new Date(d+'T12:00:00Z');return `${x.getUTCMonth()+1}月${x.getUTCDate()}日`}
function money(x){return x==null?'待核实':'S$'+Number(x).toFixed(2)}
function count(n){return Number(n).toLocaleString('en-SG',{maximumFractionDigits:1})}
function csum(obj){return Object.values(obj).reduce((a,b)=>a+(Number(b)||0),0)}
function normalArray(a){return Array.isArray(a)?a:[]}
function ownedTools(){return state.profile.tools||[]}
function availableTool(e){if(e.requiredTools)return e.requiredTools.every(t=>ownedTools().includes(t));return !e.tools||!e.tools.length||e.tools.some(t=>ownedTools().includes(t))}
function noFreezer(){return state.profile.storage!=='freezer'}
function allergies(e){return Object.keys(e.ingredients).some(k=>((I[k].allergens||[]).some(x=>state.profile.allergens.includes(x))||(state.profile.allergens.length>0&&I[k].allergenUnknown===true)))}
function hasForbiddenStorage(e){return noFreezer()&&Object.keys(e.ingredients).some(k=>I[k].storage==='frozen')}
function dislikes(e){const terms=state.profile.dislikes.split(/[,，、\s]+/).filter(Boolean);return terms.some(t=>e.zh.includes(t)||e.en.toLowerCase().includes(t.toLowerCase()))}
function eligible(e){return availableTool(e)&&!allergies(e)&&!hasForbiddenStorage(e)&&!dislikes(e)}
function pantryOwned(k){return state.pantry.some(b=>b.ingredient===k&&b.persistent&&b.active!==false&&!isExpired(b))}
function isExpired(b){return Boolean(b.expiry&&b.expiry<today())}
function usableQty(k){if(I[k].pantry)return pantryOwned(k)?Infinity:0;return state.pantry.filter(b=>b.ingredient===k&&!b.persistent&&!isExpired(b)).reduce((s,b)=>s+Math.max(0,b.remaining||0),0)}
function totalQty(k){return state.pantry.filter(b=>b.ingredient===k&&!b.persistent).reduce((s,b)=>s+Math.max(0,b.remaining||0),0)}
function stockScore(e){let score=0;for(const [k,amount] of Object.entries(e.ingredients)){const available=usableQty(k);score+=available>=amount?7:available>0?3:0}return score}
function sortedEntries(type){const score=([k,e])=>{const mood=ui.flow?.mood||'normal';const fav=state.profile.tastes||[];const tags=e.moods||['normal'];let s=stockScore(e)*5-e.minutes*.05-mealCost({baseId:k})*.3;if(Number(state.profile.kcal)>0)s-=Math.abs(mealCalories({baseId:k})-(type==='base'?Number(state.profile.kcal)*.65:Number(state.profile.kcal)*.3))*.008;if(tags.includes(mood))s+=mood==='lean'?13:10;if(mood==='light'&&e.minutes<=15)s+=2;if(mood==='indulgent'&&(e.ingredients.cheese||e.ingredients.nuggets||e.ingredients.luosifen))s+=4;if(mood==='lean'&&e.ingredients.chicken)s+=3;if(ui.flow?.slot==='breakfast'&&type==='base'&&e.minutes<=12)s+=5;if(fav.includes('spicy')&&(e.ingredients.luosifen||e.ingredients.kimchi))s+=3;if(fav.includes('sweet')&&(e.ingredients.oats||e.ingredients.yogurt||e.ingredients.sweetpotato))s+=2;return s};return Object.entries(E).filter(([,e])=>e.type===type&&eligible(e)).sort((a,b)=>score(b)-score(a)).map(([k])=>k)}
function eligibleBases(lazy){const list=sortedEntries('base');if(lazy)return list.filter(k=>E[k].tier==='easy');return state.profile.skill==='zero'?[...list.filter(k=>E[k].tier==='easy'),...list.filter(k=>E[k].tier!=='easy')]:[...list.filter(k=>E[k].tier!=='easy'),...list.filter(k=>E[k].tier==='easy')]}
function recipeMeal(flow){if(!flow)return null;return {baseId:flow.base||null,dishId:flow.dish||null,snackId:flow.snack||null,kind:'home',addons:[...(flow.addons||[])]}}
function mealIngredients(meal){const o={};for(const id of [meal.baseId,meal.dishId,meal.snackId,...(meal.addons||[])]){if(!id||!E[id])continue;for(const [k,q]of Object.entries(E[id].ingredients))o[k]=(o[k]||0)+q}return o}
function mealCalories(meal){return Math.round(Object.entries(mealIngredients(meal)).reduce((s,[k,q])=>s+(I[k].kcal||0)*q,0))}
function mealName(meal){if(!meal||meal.kind==='outside')return'出去吃';if(meal.kind==='delivery')return'点外卖';if(meal.kind==='skipped')return'跳过';return [meal.baseId,meal.dishId,meal.snackId,...(meal.addons||[])].filter(Boolean).map(k=>E[k]?.zh).filter(Boolean).join(' + ')||'简餐'}
function mealCost(meal){let cost=0;for(const [k,q]of Object.entries(mealIngredients(meal))){if(I[k].pantry){if(!pantryOwned(k))cost+=(C[k]?.price||0);continue}cost+=q/(C[k]?.pack||1)*(state.priceOverrides[k]??C[k]?.price??0)}return cost}
function canBeBought(k){return !noFreezer()||I[k].storage!=='frozen'}
function plannedMeals(){return state.plans.filter(p=>p.date>=today()&&!state.logs.some(l=>l.date===p.date&&l.slot===p.slot))}
function shoppingNeeds(){const needs={};for(const p of plannedMeals()){if(p.kind!=='home')continue;for(const [k,n]of Object.entries(mealIngredients(p)))needs[k]=(needs[k]||0)+n}return needs}
function shopLines(){return Object.entries(shoppingNeeds()).map(([k,demand])=>{const have=usableQty(k);const remaining=Math.max(0,demand-have);const pack=C[k]?.pack||1;const packs=Math.ceil(remaining/pack);return {k,demand,have,remaining,pack,packs,price:(state.priceOverrides[k]??C[k]?.price??null)}}).filter(x=>x.packs>0).sort((a,b)=>I[a.k].aisle.localeCompare(I[b.k].aisle))}
function expiryStatus(b){if(!b.expiry)return null;const diff=Math.ceil((new Date(b.expiry+'T12:00:00Z')-new Date(today()+'T12:00:00Z'))/86400000);if(diff<0)return{label:b.dateType==='bestbefore'?'已过最佳食用期·请检查':'已过使用期限·请勿使用',type:'red'};if(diff<=2)return{label:`${diff}天后到期`,type:'orange'};return{label:`${dateZh(b.expiry)} 到期`,type:'green'}}
function perishableAlerts(){return state.pantry.filter(b=>!b.persistent&&b.remaining>0&&b.expiry).map(b=>({...b,status:expiryStatus(b)})).filter(b=>b.status?.type!=='green')}
function flash(s){let t=document.querySelector('.toast');if(t)t.remove();t=document.createElement('div');t.className='toast';t.textContent=s;document.body.appendChild(t);setTimeout(()=>{if(t.isConnected)t.remove()},3200)}
function navTo(page){ui.page=page;ui.modal=null;render();window.scrollTo({top:0,behavior:'instant'})}
const glyph={home:'⌂',choose:'◉',planner:'▦',pantry:'▧',shopping:'▤',checkin:'✓',profile:'◎'};
const labels={home:'首页',choose:'选一顿',planner:'一周菜单',pantry:'我的库存',shopping:'买菜清单',checkin:'打卡',profile:'我的设置'};
function navBtn(key){return `<button class="nav-button ${ui.page===key?'active':''}" data-nav="${key}"><span class="nav-icon">${glyph[key]}</span>${labels[key]}</button>`}
function mobileNavBtn(key){return `<button class="mobile-nav ${ui.page===key?'active':''}" data-nav="${key}"><span>${glyph[key]}</span><span>${key==='choose'?'选餐':key==='shopping'?'买菜':key==='pantry'?'库存':labels[key]}</span></button>`}
function shell(body){return `<div class="layout"><aside class="sidebar"><div class="brand"><div class="logo">e.</div><div><div class="brand-title">Eat Lah</div><div class="brand-sub">Eat Lah · Singapore</div></div></div><nav class="nav">${['home','choose','planner','pantry','shopping','checkin','profile'].map(navBtn).join('')}</nav><div class="sidebar-foot">Made for life in Singapore.<br>给新加坡留学生与打工人的一顿饭。</div></aside><main class="main"><div class="topbar"><span class="topbar-text"><span class="brand-top" style="display:none">Eat Lah</span>选餐 · 买菜 · 做饭</span><div class="topbar-right"><button class="round-icon" aria-label="临期库存" title="临期库存" data-nav="pantry">♧${perishableAlerts().length?'<span class="dot"></span>':''}</button><button class="round-icon" aria-label="设置" title="设置" data-nav="profile">☺</button></div></div><div class="content">${body}<div class="subtle-foot">Eat Lah V1.2 · 原型数据仅存于当前浏览器。商品价格、热量和包装规格是演示估算，不是超市实时数据。食品安全请遵循包装说明。</div></div></main><div class="mobilebar">${['home','choose','planner','pantry','shopping','checkin'].map(mobileNavBtn).join('')}</div></div>`}
function pageHead(title,desc='',action=''){return `<div class="page-head"><div class="eyebrow">Eat Lah · Singapore</div><div class="between"><h1 class="title-lg">${title}</h1>${action}</div>${desc?`<p class="page-sub">${desc}</p>`:''}</div>`}
function btn(text,action,style='primary',extra=''){return `<button class="btn ${style}" data-action="${action}" ${extra}>${text}</button>`}
function ingName(k){return `<span>${I[k].zh}<span class="word-english">${I[k].en}</span></span>`}
function qtyLabel(k,q){return `${count(q)}${I[k].unit==='g'?'g':I[k].unit}`}
function dot(k){return ({egg:'🥚',tomato:'🍅',rice:'🍚',instant:'🍜',dumplings:'🥟',pie:'🫓',nuggets:'🍗',fries:'🍟',greens:'🥬',tofu:'⬜',oil:'🫒',salt:'🧂',soySauce:'🫙',vinegar:'🫙',pepper:'🫙',banana:'🍌',bread:'🍞',chicken:'🍗',mushroom:'🍄',broccoli:'🥦'})[k]||'🛒'}
function renderHome(){const p=state.profile;const qty=state.pantry.filter(b=>b.persistent?b.active!==false:b.remaining>0).length;const todayLogs=state.logs.filter(l=>l.date===today());const soon=perishableAlerts();return `<div class="page-head"><h1 class="title-lg">今天吃哪一顿？</h1><p class="page-sub">选择餐次后，再决定吃什么。</p></div><div class="grid3 meal-first">${[['breakfast','早餐','Breakfast','☀'],['lunch','午餐','Lunch','◐'],['dinner','晚餐','Dinner','☾']].map(([slot,zh,en,icon])=>`<button class="action-tile meal-slot" data-action="choose-slot" data-slot="${slot}"><div><div class="mode-icon">${icon}</div><div class="action-title">${zh}</div><div class="action-description">${en}</div></div><span>→</span></button>`).join('')}</div><div class="grid3 compact-stats"><div class="surface stat"><span class="tiny muted">库存 · Pantry</span><b>${qty}</b><em>种库存批次</em></div><div class="surface stat"><span class="tiny muted">今天 · Logged</span><b>${todayLogs.length}<small> / 3</small></b><em>餐已记录</em></div><div class="surface stat"><span class="tiny muted">每周预算</span><b>S$${esc(p.budget)}</b><em>Weekly budget</em></div></div>${soon.length?`<div class="alert warning" style="margin-top:16px">有 ${soon.length} 批食材临期或需检查。<button class="mini-link" data-nav="pantry">查看库存 →</button></div>`:''}<div class="hrow" style="margin-top:22px;flex-wrap:wrap">${btn('安排 3 / 7 天菜单','open-planner','secondary')}${btn('查看库存','open-pantry','ghost')}${btn('查看打卡','open-checkin','ghost')}</div>`}
function storageChoices(){return [['small','有冷藏 / Refrigeration'],['freezer','有冷冻（也有冷藏） / Freezer + fridge'],['none','都没有 / Neither']]}
function budgetPicker(){const p=state.profile;return `<div class="sub-section"><h3 class="step-title">买菜预算 · Weekly groceries</h3><div class="check-group">${[[40,'S$40 · 节约'],[70,'S$70 · 日常'],[110,'S$110 · 更丰富']].map(([n,label])=>`<button class="check-chip ${Number(p.budget)===n?'selected':''}" data-budget-preset="${n}">${label}</button>`).join('')}</div><label class="field" style="margin-top:12px"><span class="field-label">自行修改：每周 S$（1 人）</span><input type="number" min="0" max="9999" step="5" data-profile="budget" value="${esc(p.budget)}" /></label><div class="guidance-note">一人每周自炊买菜的起始预算示例，<b>不是固定市场价</b>。买菜的次数、食量、海鲜或进口商品、整包购买都会影响实际费用；外食和外卖另计。第一次买米、油和调味品可能明显超支。</div></div>`}
function kcalPicker(){const p=state.profile;return `<div class="sub-section"><h3 class="step-title">每餐热量 · kcal / meal（可选）</h3><div class="check-group">${[[0,'不限制'],[450,'约 450 · 轻一些'],[600,'约 600 · 常规'],[750,'约 750 · 较饱']].map(([n,label])=>`<button class="check-chip ${Number(p.kcal)===n?'selected':''}" data-kcal-preset="${n}">${label}</button>`).join('')}</div><label class="field" style="margin-top:12px"><span class="field-label">自己设置（0 表示不限制）</span><input type="number" min="0" max="2000" step="50" data-profile="kcal" value="${esc(p.kcal)}" /></label><div class="guidance-note">新加坡 HealthHub 提供的<b>一般每日参考</b>约为女性 1,800 kcal、男性 2,200 kcal；个人需要因年龄、身高、活动量等不同。减脂也没有人人通用的单餐数字，宜根据个人每日需求决定；这里的 450/600/750 只是筛选示例，不是个性化健康建议。</div></div>`}
function renderSetup(){const p=state.profile;const step=ui.onboardStep;const parts=[['你的新加坡生活','先设置住处区域与厨具。'],['预算和热量','没有概念也没关系，可按参考选择或跳过。'],['饮食喜好','确认忌口和喜欢的味道。'],['常备调味品','买过的调味品可以保持常备状态。']];let content='';if(step===0){content=`<div class="setting-grid"><label class="field"><span class="field-label">怎么称呼你 / Name（选填）</span><input data-profile="nickname" value="${esc(p.nickname)}" placeholder="例如：Alex" /></label><label class="field"><span class="field-label">新加坡邮编 / Postal code（6 位）</span><input data-profile="postal" inputmode="numeric" maxlength="6" value="${esc(p.postal)}" placeholder="例如：123456" /></label></div><div class="guidance-note" style="margin-top:12px">不用先知道去哪家超市。以后会按邮编查找附近购物地点；目前原型会打开地图搜索，真实距离排名需接入地理位置和已验证的门店数据。</div><div class="field" style="margin-top:15px"><span class="field-label">地址备注 / Address note（选填）</span><input data-profile="address" value="${esc(p.address)}" placeholder="例如：住在 Clementi 一带，无需具体门牌" /></div><div class="sub-section"><h3 class="step-title">你有哪些厨具？</h3><div class="option-grid">${D.tools.map(t=>`<button class="option ${p.tools.includes(t.id)?'selected':''}" data-tool="${t.id}"><span class="symbol">${t.icon}</span>${t.name}<small>${t.en}</small></button>`).join('')}</div></div><div class="sub-section"><h3 class="step-title">你能保存哪些食物？</h3><div class="check-group">${storageChoices().map(([k,v])=>`<button class="check-chip ${p.storage===k?'selected':''}" data-set="storage" data-value="${k}">${v}</button>`).join('')}</div><div class="guidance-note">没有冷藏设施时，软件应建议易腐食材按餐购买；有冷冻时才能推荐需要长期冷冻保存的整袋速食。</div></div>`}
if(step===1){content=`${budgetPicker()}${kcalPicker()}`}
 if(step===2){content=`<h3 class="step-title">你有没有过敏或必须避开的食材？</h3><p class="small muted">过敏限制会一直生效，不能因推荐结果少而自动放宽。</p><div class="check-group">${D.allergens.map(x=>`<button class="check-chip ${p.allergens.includes(x.id)?'selected':''}" data-allergen="${x.id}">${x.name} · ${x.en}</button>`).join('')}</div><div class="sub-section"><label class="field"><span class="field-label">不喜欢的食物 / Foods to avoid</span><input data-profile="dislikes" value="${esc(p.dislikes)}" placeholder="例如：蘑菇、番茄（用逗号分开）" /></label></div><div class="sub-section"><h3 class="step-title">平时喜欢什么味道？（可多选）</h3><div class="check-group">${[['spicy','辣 / Spicy'],['sweet','甜 / Sweet'],['savory','咸香 / Savory'],['light','清淡 / Mild']].map(([k,v])=>`<button class="check-chip ${p.tastes.includes(k)?'selected':''}" data-taste="${k}">${v}</button>`).join('')}</div></div><div class="sub-section"><h3 class="step-title">能接受多复杂的做法？</h3><div class="check-group">${[['zero','尽量不动手'],['new','简单一锅 15 分钟'],['normal','愿意做一道菜']].map(([k,v])=>`<button class="check-chip ${p.skill===k?'selected':''}" data-set="skill" data-value="${k}">${v}</button>`).join('')}</div></div>`}
if(step===3){content=`<h3 class="step-title">你现在已经有哪些调料？</h3><p class="small muted">初次没有也没关系，买完后会从双语购物清单自动加入“常备调料”。</p><div class="grid2">${D.seasonings.map(k=>`<button class="action-tile" data-setup-seasoning="${k}"><span class="hrow"><span>${dot(k)}</span><span><b>${I[k].zh}</b><span class="word-english">${I[k].en}</span></span></span><span class="checkbox ${ui.setupSeasonings.includes(k)||pantryOwned(k)?'checked':''}">${ui.setupSeasonings.includes(k)||pantryOwned(k)?'✓':''}</span></button>`).join('')}</div><div class="alert warning" style="margin-top:20px">常备 ≠ 永不过期：系统默认不按菜谱扣调味品数量，但用户可以标记用完；如包装有 Use By / Best Before 或开封储存要求，仍应遵守。</div>`}
return `<div class="onboard"><div class="onboard-header"><div class="logo">e.</div><div><b style="font-size:19px">Eat Lah</b><div class="onboard-step">FIRST THINGS FIRST · ${step+1} / ${parts.length}</div></div></div><div class="progress">${parts.map((_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><h1 class="title-lg">${parts[step][0]}</h1><p class="lead">${parts[step][1]}</p><div class="surface pad">${content}</div><div class="between" style="margin-top:20px">${step?btn('← 上一步','setup-back','secondary'):'<div></div>'}${btn(step===3?'好了，开始吃饭 →':'下一步 →','setup-next')}</div><p class="tiny muted" style="margin-top:18px">隐私说明：这个可操作原型仅在当前浏览器保存资料；尚未启用真实用户账号或云端同步。地址可以留空。</p></div>`}
function begin(mode='cook',slot=null){ui.flow={mode,step:slot?'effort':'slot',slot,mood:'normal',base:null,dish:null,snack:null,addons:[],skips:{base:[],dish:[],snack:[],lazyhome:[]},lazyPlace:null};if(slot)ui.checkSlot=slot;navTo('choose')}
function candidates(step){if(!ui.flow)return[];const f=ui.flow;let keys=[];if(step==='base')keys=eligibleBases(false);if(step==='lazyhome')keys=eligibleBases(true);if(step==='dish')keys=sortedEntries('dish');if(step==='snack')keys=sortedEntries('snack');return keys.filter(k=>!f.skips[step]?.includes(k))}
function activeCard(){const f=ui.flow;return f?candidates(f.step)[0]||null:null}
function progressBar(active){const steps=['base','dish','snack','summary'];const i=steps.indexOf(active);return `<div class="progress">${steps.slice(0,3).map((_,j)=>`<span class="${j<=i?'done':''}"></span>`).join('')}</div>`}
function cardWhy(k){const e=E[k];const needs=Object.entries(e.ingredients).filter(([id,q])=>usableQty(id)<q).length;return `${needs===0?'当前库存足够':`需补购 ${needs} 种食材`} · ${e.tools.length?e.tools.map(t=>D.tools.find(x=>x.id===t)?.name).filter(Boolean).join(' / '):'无需专用厨具'}`}
function foodCard(k){const e=E[k];return `<div class="food-card" id="swipe-card"><div class="food-visual"><span>${e.emoji}</span></div><div class="food-body"><div class="eyebrow">${e.type==='base'?'MAIN MEAL':e.type==='dish'?'ONE EASY DISH':'OPTIONAL SIDE'}</div><h2>${esc(e.zh)}</h2><div class="bilingual">${esc(e.en)}</div><div class="pills" style="margin-top:12px"><span class="pill">${e.minutes} 分钟</span><span class="pill ${Object.entries(e.ingredients).every(([k,q])=>usableQty(k)>=q)?'green':''}">${Object.entries(e.ingredients).every(([k,q])=>usableQty(k)>=q)?'库存够用':'有材料要补购'}</span><span class="pill">约 ${mealCalories({baseId:k})} kcal*</span></div><div class="line"></div><div class="small strong">主要材料</div><p class="small muted">${Object.entries(e.ingredients).map(([x,q])=>I[x].zh+' '+qtyLabel(x,q)).join(' · ')}</p>${e.tip?`<div class="small muted">${esc(e.tip)}</div>`:''}</div></div>`}
function renderFlow(){const f=ui.flow;
if(!f||f.step==='slot')return `${pageHead('选一顿饭','先决定早餐、午餐还是晚餐。')}<div class="grid3 meal-first">${[['breakfast','早餐','Breakfast'],['lunch','午餐','Lunch'],['dinner','晚餐','Dinner']].map(([slot,zh,en])=>`<button class="action-tile meal-slot" data-action="choose-slot" data-slot="${slot}"><div><div class="action-title">${zh}</div><div class="action-description">${en}</div></div><span>→</span></button>`).join('')}</div>`;
if(f.step==='effort')return `${pageHead(`${slotLabel(f.slot)} · 今天想怎么吃？`,'根据你今天愿意花的精力，帮你缩小范围。')}<div class="grid2 mood-grid"><button class="action-tile" data-action="choose-effort" data-value="cook"><div><div class="action-title">我想做点</div><div class="action-description">从主食开始，可选一道配菜和小食；泡面、半成品也在其中。</div></div><span>→</span></button><button class="action-tile" data-action="choose-effort" data-value="lazy"><div><div class="action-title">今天省点事</div><div class="action-description">在家简单吃、出去吃，或者点外卖。</div></div><span>→</span></button></div><div style="margin-top:18px">${btn('← 改选餐次','flow-back','ghost')}</div>`;
 if(f.step==='mood')return `${pageHead(`${slotLabel(f.slot)} · 想吃哪种？`,'按今天的心情选；忌口和厨具仍然优先。')}<div class="grid2 mood-grid">${[['light','清淡','Light'],['normal','普通','Everyday'],['indulgent','罪恶','Comfort food'],['lean','减脂','Lighter choice'],['surprise','你看着办','Surprise me']].map(([m,zh,en])=>`<button class="action-tile" data-action="choose-mood" data-value="${m}"><div><div class="action-title">${zh}</div><div class="action-description">${en}</div></div><span>→</span></button>`).join('')}</div><div style="margin-top:18px">${btn('← 改选餐次','flow-back','ghost')}</div>`;
if(f.step==='lazytype')return `${pageHead('这顿怎么解决？','在家简单吃、外食或外卖。')}<div class="grid3 meal-first"><button class="action-tile" data-action="lazy-home"><div><div class="action-title">在家吃</div><div class="action-description">库存和速食优先</div></div><span>→</span></button><button class="action-tile" data-action="lazy-out"><div><div class="action-title">出去吃</div><div class="action-description">附近餐饮</div></div><span>→</span></button><button class="action-tile" data-action="lazy-delivery"><div><div class="action-title">点外卖</div><div class="action-description">不扣库存</div></div><span>→</span></button></div>`;
if(f.step==='lazyexternal'){const q=encodeURIComponent((f.lazyPlace==='outside'?'restaurants near ':'food delivery near ')+(state.profile.postal||'Singapore')+' Singapore');const url='https://www.google.com/maps/search/?api=1&query='+q;return `${pageHead(f.lazyPlace==='outside'?'出去吃':'点外卖','当前版本提供地图搜索入口，不展示未经核实的商家。')}<div class="surface pad"><a class="btn secondary" target="_blank" rel="noopener noreferrer" href="${url}">搜索附近选择 ↗</a><div class="line"></div>${btn('这顿完成，记录'+slotLabel(f.slot),'log-external','primary',`data-slot="${f.slot}"`)}</div>`}
if(f.step==='summary'){const meal=recipeMeal(f),items=Object.entries(mealIngredients(meal)),missing=items.filter(([k,q])=>usableQty(k)<q);const addonIDs=(E[f.base]?.addons||[]).filter(k=>E[k]&&eligible(E[k]));return `${pageHead(`${slotLabel(f.slot)} · 选好了`,'确认搭配后进入购物清单；已有库存会优先使用。')}<div class="split"><div class="surface pad"><h2 class="title-lg">${mealName(meal)}</h2><div class="pills"><span class="pill">约 ${mealCalories(meal)} kcal*</span><span class="pill">演示食材成本 ${money(mealCost(meal))}</span></div>${addonIDs.length?`<div class="line"></div><div class="small strong">可选加料（不加也可以）</div><div class="check-group" style="margin-top:12px">${addonIDs.map(k=>`<button class="check-chip ${f.addons.includes(k)?'selected':''}" data-action="toggle-addon" data-key="${k}">${esc(E[k].zh)}</button>`).join('')}</div>`:''}<div class="line"></div><h3 class="section-title">需要的食材 · Ingredients</h3>${items.map(([k,q])=>`<div class="recipe-line"><div>${ingName(k)}</div><div style="text-align:right"><b>${I[k].pantry?(pantryOwned(k)?'常备':'需购买'):qtyLabel(k,q)}</b><div class="bilingual">${usableQty(k)>=q?'库存够用':'待补购'}</div></div></div>`).join('')}<div class="alert ${missing.length?'warning':''}" style="margin-top:15px">${missing.length?`需要补购 ${missing.length} 种食材，系统将按整包装生成清单。`:'库存已覆盖本餐食材，无需额外购买。'}</div><div class="hrow" style="margin-top:20px;flex-wrap:wrap">${btn('确认并查看购物清单','save-meal')}${btn('预览做法','recipe-modal','secondary')}</div></div><div class="surface pad"><h3 class="section-title">${slotLabel(f.slot)} · ${({light:'清淡',normal:'普通',indulgent:'罪恶',lean:'减脂',surprise:'随机'})[f.mood]||'普通'}</h3><p class="small muted">选好这顿后会依次进入购物清单、做饭步骤和一键完成。</p><div class="alert warning">*热量、包装和价格目前为演示估算。复杂加热与食品安全以实际包装为准。</div>${btn('返回修改','flow-back','secondary','style="width:100%"')}</div></div>`}
const step=f.step,k=activeCard(),stepName={base:'选这顿的主食',dish:'要搭一道菜吗？',snack:'要加一份小食吗？',lazyhome:'家里简单吃'}[step];return `${pageHead(`${slotLabel(f.slot)} · ${stepName}`, '每次只有一张卡片。喜欢就留下，不喜欢就换。')}${progressBar(step)}<div class="flow-layout"><div class="flow-panel surface">${k?`${foodCard(k)}<div class="hrow" style="margin-top:15px"><button class="btn secondary" style="flex:1" data-action="flow-reject">换一个</button><button class="btn primary" style="flex:1" data-action="flow-accept">就这个</button></div><div class="swipe-guide">向左划走 · 向右保留</div>`:`<div class="empty"><h3>目前没有更多符合条件的选择</h3><p>可以调整厨具或忌口，或者直接进入下一步。</p></div>`}<div class="hrow" style="justify-content:space-between;margin-top:14px">${btn('← 返回','flow-back','ghost')}${btn(step==='base'?'直接看省事的 →':'跳过这一步 →','flow-skip','ghost')}</div>${step==='base'?`<div style="margin-top:12px">${btn('今天不想做了','go-lazy','secondary','style="width:100%"')}</div>`:''}</div><div class="flow-aside"><div class="surface pad"><h3 class="section-title">匹配原因</h3><p class="small muted">${k?cardWhy(k):'没有符合当前条件的候选'}</p><div class="line"></div><div class="small strong">当前厨具</div><div class="pills" style="margin-top:10px">${(ownedTools().length?ownedTools():['未设置']).map(t=>`<span class="pill">${esc(D.tools.find(x=>x.id===t)?.name||t)}</span>`).join('')}</div></div></div></div>`;
}
function slotLabel(x){return {breakfast:'早餐',lunch:'午餐',dinner:'晚餐'}[x]||x}
function recordMeal(meal,slot,date=today()){if(state.logs.some(l=>l.date===date&&l.slot===slot)){flash('这顿已经打卡了，可先撤销再重新记录。');return false}const used=[];if(meal.kind==='home'){for(const [k,amount] of Object.entries(mealIngredients(meal))){if(I[k].pantry)continue;let left=amount;const batches=state.pantry.filter(b=>b.ingredient===k&&!b.persistent&&b.remaining>0&&!isExpired(b)).sort((a,b)=>(a.expiry||'9999').localeCompare(b.expiry||'9999')||(a.purchased||'').localeCompare(b.purchased||''));for(const b of batches){const n=Math.min(b.remaining,left);if(n<=0)continue;b.remaining-=n;left-=n;used.push({batchId:b.id,ingredient:k,qty:n});if(left<=0)break}}}const log={id:id(),date,slot,kind:meal.kind||'home',mealName:mealName(meal),meal:{...meal},used,created:new Date().toISOString()};state.logs.push(log);state.transactions.push({id:id(),kind:'meal',logId:log.id,date:log.created,items:used});save();return true}
function undoLog(logId){const l=state.logs.find(x=>x.id===logId);if(!l)return;for(const u of l.used||[]){const b=state.pantry.find(x=>x.id===u.batchId);if(b)b.remaining+=u.qty}state.logs=state.logs.filter(x=>x.id!==logId);state.transactions.push({id:id(),kind:'undo_meal',logId,date:new Date().toISOString()});save();flash('已撤销该顿记录，库存已恢复。');render()}
function renderPlanner(){const ps=state.plans.slice().sort((a,b)=>a.date.localeCompare(b.date)||['breakfast','lunch','dinner'].indexOf(a.slot)-['breakfast','lunch','dinner'].indexOf(b.slot));const dates=[...new Set(ps.map(x=>x.date))];return `${pageHead('这一周，吃什么？','不用连选 21 次。先自动安排，不喜欢的再换。',btn('↻ 重新安排','generate-plan','secondary compact'))}<div class="surface pad"><div class="between"><div><h3 class="section-title">生成菜单 / Meal planner</h3><div class="bilingual">选择天数，自动安排早餐、午餐和晚餐</div></div><div class="tabrow">${[3,7].map(d=>`<button class="tab ${ui.planDays===d?'active':''}" data-days="${d}">${d} 天</button>`).join('')}</div></div><div style="margin-top:16px" class="hrow">${btn('生成 '+ui.planDays+' 天菜单','generate-plan')}${btn('加一顿今天的饭','start-cook','secondary')}</div></div>${!ps.length?`<div class="empty"><div class="emoji">▦</div><h3>还没有安排菜单</h3><p>点击“生成菜单”，系统会按现有库存、厨具与忌口选择容易操作的组合。</p></div>`:`<div class="section-head"><h2 class="section-title">你的菜单</h2><span class="tiny muted">${dates.length} 天 · ${ps.length} 餐</span></div><div class="grid2">${dates.map(date=>`<div class="surface plan-day"><div class="between"><h3>${dateZh(date)}</h3><span class="tiny muted">${date}</span></div>${['breakfast','lunch','dinner'].map(slot=>{const m=ps.find(p=>p.date===date&&p.slot===slot);const log=state.logs.find(l=>l.date===date&&l.slot===slot);return `<div class="plan-meal"><div style="min-width:0;flex:1"><div class="meal-label">${slotLabel(slot)} · ${({breakfast:'Breakfast',lunch:'Lunch',dinner:'Dinner'})[slot]}</div><div class="meal-name">${m?esc(mealName(m)):'未安排'}</div></div><div class="hrow">${log?'<span class="day-status">✓ 已打卡</span>':m&&date===today()?`<button class="mini-link" data-action="eat-plan" data-id="${m.id}">吃了 ✓</button>`:''}${m&&!log?`<button title="换一顿" class="mini-link" data-action="swap-plan" data-id="${m.id}">↻</button>`:''}</div></div>`}).join('')}</div>`).join('')}</div><div style="margin-top:22px">${btn('查看统一购物清单 →','open-shopping')}</div>`}`}
function pickMeal(index=0,slot='dinner'){let bases=eligibleBases(false);if(slot==='breakfast')bases=[...bases.filter(x=>['toast','porridge','ricepack','instant'].includes(x)),...bases.filter(x=>!['toast','porridge','ricepack','instant'].includes(x))];if(!bases.length)return null;const baseId=bases[index%bases.length];const dishs=sortedEntries('dish');const dishId=slot==='breakfast'?null:((index%3===0&&dishs.length)?dishs[index%dishs.length]:null);return {kind:'home',baseId,dishId,snackId:null}}
function generatePlan(){const days=ui.planDays;const all=[];let n=0;for(let i=0;i<days;i++)for(const slot of ['breakfast','lunch','dinner']){const meal=pickMeal(n++,slot);if(!meal){flash('当前厨具与忌口条件下没有合适的餐食，请调整设置。');return}all.push({id:id(),date:addDay(today(),i),slot,...meal})}state.plans=all;save();flash(`已安排 ${days} 天、${all.length} 餐。`);render()}
function renderShopping(){const lines=shopLines();const total=lines.reduce((s,x)=>s+x.packs*(x.price||0),0);const totalDemo=lines.every(x=>x.price!=null);const budget=Number(state.profile.budget)||0;const en=ui.receipt;const info=`<div class="alert warning">页面中的商品包装、售价和热量是用于开发的示例数据，非 FairPrice 等超市的实时商品资料。你可以在买完菜后用真实收据改价格；后续版本将接入核实过的 SKU。</div>`;
const receipt=`<div class="receipt"><div class="between"><div><h3 class="receipt-title">Shopping list</h3><div class="bilingual">Eat Lah · Show this to supermarket staff</div></div><span class="badge-count">${lines.length} items</span></div>${lines.map(x=>`<div class="receipt-line"><div class="english">${esc(I[x.k].en)}<div class="chinese">${I[x.k].zh} · ${esc(C[x.k].label)}</div></div><b>× ${x.packs}</b></div>`).join('')}<div class="line"></div><div class="small">Excuse me, where can I find these items?</div><div class="bilingual">不好意思，请问这些商品在哪里？</div></div>`;
return `${pageHead('买菜清单 · Shopping list','合并一周需要的材料，英文名称可以直接给新加坡超市工作人员看。')}<div class="grid3"><div class="surface stat"><span class="tiny muted">缺少商品</span><b>${lines.length}</b><em>Items to buy</em></div><div class="surface stat"><span class="tiny muted">示例结账价</span><b style="font-size:19px">${money(totalDemo?total:null)}</b><em>Estimated only</em></div><div class="surface stat"><span class="tiny muted">周预算目标</span><b>S$${budget}</b><em>Weekly target</em></div></div><div class="section-head"><h2 class="section-title">要买什么</h2><div class="hrow"><button class="mini-link" data-action="toggle-receipt">${en?'返回购物勾选':'英文展示模式'}</button><button class="mini-link" data-action="copy-shopping">复制英文清单</button></div></div>${info}<div style="height:15px"></div>${!lines.length?`<div class="surface empty"><div class="emoji">🧺</div><h3>现在没有需要补购的商品</h3><p>${state.plans.length?'库存已覆盖计划内的需求。':'先选一顿饭或生成 3/7 天菜单，自动得到合并清单。'}</p>${btn('去安排吃什么','open-choose','soft')}</div>`:en?receipt:`<div class="surface pad">${lines.map(x=>{const checked=ui.cartCheck[x.k]!==false;const packs=ui.cartPacks[x.k]??x.packs;return `<div class="item-row"><button class="checkbox ${checked?'checked':''}" data-action="cart-check" data-key="${x.k}">${checked?'✓':''}</button><div class="item-emoji">${dot(x.k)}</div><div class="item-main"><div class="item-title">${I[x.k].zh}</div><div class="item-sub">${I[x.k].en} · ${C[x.k].label}</div><div class="bilingual">需要 ${qtyLabel(x.k,x.remaining)} · 示例商品包装</div></div><div class="item-right"><div class="price">${money(x.price==null?null:x.price*packs)}</div><div class="hrow"><button class="mini-link" data-action="pack-minus" data-key="${x.k}">−</button><span class="badge-count">${packs} ${packs===1?'包':'包'}</span><button class="mini-link" data-action="pack-plus" data-key="${x.k}">＋</button></div></div></div>`}).join('')}<div class="between" style="margin-top:20px"><div class="small muted">确认后自动按整包装加入库存</div>${btn('✓ 这些我买好了','confirm-shopping')}</div></div>`}<div class="section-head"><h2 class="section-title">附近在哪里买？ / Where to shop</h2></div><div class="surface pad"><p class="small muted" style="margin-top:0">${state.profile.postal?`已使用邮编 ${esc(state.profile.postal)} 附近搜索。`:'尚未设置邮编，先以 Singapore 作为搜索区域。'}目前会通过邮编打开地图搜索，尚未在软件内核验、排序具体门店或商品可售情况。</p><div class="pills"><a class="btn secondary compact" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent('supermarket near '+(state.profile.postal||'Singapore')+' Singapore')}">搜索附近超市 ↗</a><a class="btn secondary compact" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent('Asian grocery store near '+(state.profile.postal||'Singapore')+' Singapore')}">搜索附近亚超 ↗</a></div></div>`}
function buyShopping(){const lines=shopLines();const chosen=lines.filter(x=>ui.cartCheck[x.k]!==false&&(ui.cartPacks[x.k]??x.packs)>0);if(!chosen.length){flash('先选中实际购买的商品。');return}for(const x of chosen){const qty=(ui.cartPacks[x.k]??x.packs)*x.pack;const existing=I[x.k].pantry&&state.pantry.some(b=>b.ingredient===x.k&&b.persistent&&b.active!==false);if(existing)continue;const b={id:id(),ingredient:x.k,initial:qty,remaining:qty,persistent:Boolean(I[x.k].pantry),active:true,purchased:today(),expiry:null,dateType:'useby',storage:I[x.k].storage,source:'shopping_confirmation',isEstimate:false};state.pantry.push(b);state.purchaseHistory.push({id:id(),date:today(),ingredient:x.k,qty,packs:(ui.cartPacks[x.k]??x.packs),packSize:x.pack,price:x.price})}state.transactions.push({id:id(),kind:'purchase',date:new Date().toISOString(),items:chosen.map(x=>({ingredient:x.k,qty:(ui.cartPacks[x.k]??x.packs)*x.pack}))});ui.cartCheck={};ui.cartPacks={};save();flash('已记录本次购买。现在可以开始做饭。');navTo('cook')}
function currentCookingMeal(){return state.plans.find(p=>p.id===ui.activeMealId)||state.plans.find(p=>p.date===today()&&p.slot===ui.checkSlot)||null}
function renderCook(){const m=currentCookingMeal();if(!m)return `${pageHead('开始做饭','请先选择并保存一顿餐食。')}${btn('开始选餐','start-cook')}`;const keys=[m.baseId,m.dishId,m.snackId,...(m.addons||[])].filter(Boolean).filter(k=>E[k]);const missing=Object.entries(mealIngredients(m)).filter(([k,q])=>usableQty(k)<q);return `${pageHead(`${slotLabel(m.slot)} · 开始做饭`,'按下面的步骤操作。做完只需要点击一次“完成”。')}<div class="surface pad"><h2 class="title-lg">${esc(mealName(m))}</h2>${missing.length?`<div class="alert warning" style="margin-top:16px">当前库存还缺 ${missing.length} 项原料。如果已经实际买到，请先确认购买并入库。${btn('查看购物清单','open-shopping','secondary compact')}</div>`:'<div class="pill green" style="margin-top:12px">食材库存已覆盖本餐</div>'}${keys.map(k=>`<div class="sub-section"><div class="hrow" style="align-items:center"><span style="font-size:32px">${E[k].emoji}</span><div><h3 class="section-title">${esc(E[k].zh)}</h3><div class="bilingual">${esc(E[k].en)} · 约 ${E[k].minutes} 分钟</div></div></div><div class="small strong" style="margin:12px 0">${Object.entries(E[k].ingredients).map(([ing,q])=>I[ing].zh+' '+qtyLabel(ing,q)).join(' · ')}</div>${E[k].instructions.map((t,i)=>`<div class="instruction"><div class="step-num">${i+1}</div><div>${esc(t)}</div></div>`).join('')}${E[k].tip?`<div class="alert warning">${esc(E[k].tip)}</div>`:''}</div>`).join('')}<div class="alert warning">实际食品加热温度、过敏原、有效期及储存要求请以商品包装和设备说明为准。</div><div class="hrow" style="margin-top:20px;flex-wrap:wrap">${btn('完成这顿 · 自动打卡并扣库存','finish-cooking')}${btn('返回买菜清单','open-shopping','secondary')}</div></div>`}
function renderShopWithCooking(){const base=renderShopping();const m=currentCookingMeal();return base+(m?`<div class="surface pad" style="margin-top:18px"><h3 class="section-title">${slotLabel(m.slot)} · 下一步</h3><p class="small muted">已经买好了或家里有这些材料？直接开始跟着食谱做。</p>${btn('开始做饭 →','start-cooking')}</div>`:'')}
function renderPantry(){const buckets={};for(const b of state.pantry){if(b.persistent?b.active===false:b.remaining<=0)continue;if(!buckets[b.ingredient])buckets[b.ingredient]=[];buckets[b.ingredient].push(b)}const keys=Object.keys(buckets).filter(k=>ui.pantryFilter==='all'||(ui.pantryFilter==='seasoning')===Boolean(I[k].pantry));const alerts=perishableAlerts();return `${pageHead('我的厨房 · My pantry','不是每餐都重新记账。只在买完、吃完或者发现数量不对时操作。',btn('＋ 手动添加','add-pantry','secondary compact'))}<div class="surface pad"><div class="between"><div><h3 class="section-title">当前库存</h3><div class="bilingual">${keys.length} 种食材 · 常备调料不逐次扣减</div></div><div class="tabrow">${[['all','全部'],['seasoning','调味品'],['food','普通食材']].map(([k,v])=>`<button class="tab ${ui.pantryFilter===k?'active':''}" data-pantry-filter="${k}">${v}</button>`).join('')}</div></div>${!keys.length?`<div class="empty"><div class="emoji">🧊</div><h3>库存还是空的</h3><p>买完菜点击“买好了”，就会自动增加，不用自己输入每个数。</p>${btn('去购物清单','open-shopping','soft')}</div>`:keys.map(k=>{const batches=buckets[k];const persistent=Boolean(I[k].pantry);const quantity=totalQty(k);const statuses=batches.map(expiryStatus).filter(Boolean);const serious=statuses.find(s=>s.type==='red')||statuses.find(s=>s.type==='orange');return `<div class="item-row"><div class="item-emoji">${dot(k)}</div><div class="item-main"><div class="item-title">${I[k].zh}<span class="word-english">${I[k].en}</span></div><div class="item-sub">${persistent?'常备调味品 · 默认不逐次扣量':`剩余约 ${qtyLabel(k,quantity)} · ${batches.length} 批`}</div>${serious?`<span class="pill ${serious.type}">${serious.label}</span>`:!persistent&&batches.some(b=>!b.expiry)?'<span class="status-tag">保质期未录入 · 请看包装</span>':''}</div><div class="item-right"><button class="btn secondary compact" data-action="pantry-adjust" data-key="${k}">${persistent?'标记用完':'库存不对'}</button><button class="mini-link" data-action="pantry-expiry" data-key="${k}">查看 / 录入有效期</button></div></div>`}).join('')}</div>${alerts.length?`<div class="alert warning" style="margin-top:16px">⚠ ${alerts.length} 批库存有临期或到期标识。超过 Use By 的食材不会参与自动推荐或自动扣减。</div>`:''}<div class="section-head"><h2 class="section-title">调味品是“常备”，不是永不过期</h2></div><div class="alert">油、盐、酱油、醋等买过后会标记为常备，不逐餐扣数量；如果用完，可点“标记用完”。但仍要遵守产品标签的有效期、开封后冷藏等要求。</div>`}
function renderCheckin(){const slots=['breakfast','lunch','dinner'];return `${pageHead('今天吃了吗？','不论自己做、吃剩菜、外食还是外卖，都可以轻松打卡。')}<div class="grid3">${slots.map(s=>{const log=state.logs.find(l=>l.date===today()&&l.slot===s);return `<div class="surface stat" style="text-align:center"><div style="font-size:30px">${s==='breakfast'?'🌤':s==='lunch'?'☀️':'🌙'}</div><div style="font-weight:680;margin-top:8px">${slotLabel(s)}</div><div class="bilingual">${({breakfast:'Breakfast',lunch:'Lunch',dinner:'Dinner'})[s]}</div><div style="margin-top:12px">${log?'<span class="pill green">✓ 已打卡</span>':`<button class="btn secondary compact" data-action="check-slot" data-slot="${s}">记录这餐</button>`}</div></div>`}).join('')}</div><div class="section-head"><h2 class="section-title">打卡记录 / Meal history</h2></div><div class="surface pad">${!state.logs.length?`<div class="empty"><div class="emoji">☀️</div><h3>第一顿，随时开始</h3><p>不强制连续打卡，想记录哪天都可以。</p></div>`:state.logs.slice().reverse().slice(0,30).map(l=>`<div class="item-row"><div class="item-emoji">${l.kind==='home'?'🍚':l.kind==='outside'?'🍽':l.kind==='delivery'?'🛵':'—'}</div><div class="item-main"><div class="item-title">${esc(l.mealName)}</div><div class="item-sub">${l.date} · ${slotLabel(l.slot)} · ${l.kind==='home'?'在家吃':l.kind==='outside'?'外出就餐':l.kind==='delivery'?'外卖':'跳过'}</div></div><button class="mini-link" data-action="undo-log" data-id="${l.id}">撤销</button></div>`).join('')}</div>`}
function renderProfile(){const p=state.profile;return `${pageHead('我的设置 · My kitchen','住处区域、厨具与口味会用于下一次推荐。')}<div class="surface pad"><div class="setting-grid"><label class="field"><span class="field-label">昵称 / Name</span><input data-profile="nickname" value="${esc(p.nickname)}"></label><label class="field"><span class="field-label">新加坡邮编 / Postal code</span><input maxlength="6" inputmode="numeric" data-profile="postal" value="${esc(p.postal)}" placeholder="6 位邮编"></label></div><div class="guidance-note" style="margin-top:12px">购物地点会通过邮编查找，不需要预先选择熟悉的超市品牌。</div><div class="field" style="margin-top:15px"><span class="field-label">地址备注 / Address note（选填）</span><input data-profile="address" value="${esc(p.address)}" placeholder="只需区域或宿舍名称" /></div><div class="sub-section"><h3 class="step-title">现有厨具 · Kitchen equipment</h3><div class="option-grid">${D.tools.map(t=>`<button class="option ${p.tools.includes(t.id)?'selected':''}" data-tool="${t.id}"><span class="symbol">${t.icon}</span>${t.name}<small>${t.en}</small></button>`).join('')}</div></div><div class="sub-section"><h3 class="step-title">食物储存条件 · Storage</h3><div class="check-group">${storageChoices().map(([k,v])=>`<button class="check-chip ${p.storage===k?'selected':''}" data-set="storage" data-value="${k}">${v}</button>`).join('')}</div></div>${budgetPicker()}${kcalPicker()}<div class="sub-section"><h3 class="step-title">过敏与忌口 / Allergies</h3><div class="check-group">${D.allergens.map(x=>`<button class="check-chip ${p.allergens.includes(x.id)?'selected':''}" data-allergen="${x.id}">${x.name} · ${x.en}</button>`).join('')}</div></div><div class="sub-section"><label class="field"><span class="field-label">不喜欢的食物 / Dislikes</span><input data-profile="dislikes" value="${esc(p.dislikes)}" placeholder="番茄、蘑菇..." /></label></div><div class="sub-section"><h3 class="step-title">喜欢的口味 · Tastes</h3><div class="check-group">${[['spicy','爱辣 / Spicy'],['sweet','偏甜 / Sweet'],['savory','咸香 / Savory'],['light','清淡 / Mild']].map(([k,v])=>`<button class="check-chip ${p.tastes.includes(k)?'selected':''}" data-taste="${k}">${v}</button>`).join('')}</div></div><div class="sub-section"><h3 class="step-title">做饭偏好</h3><div class="check-group">${[['zero','能不动手就不动手'],['new','15分钟简单料理'],['normal','最多一道菜']].map(([k,v])=>`<button class="check-chip ${p.skill===k?'selected':''}" data-set="skill" data-value="${k}">${v}</button>`).join('')}</div></div><div class="between" style="margin-top:24px"><span class="small muted">所有设置改动会自动保存</span>${btn('返回首页 →','open-home')}</div></div><div class="section-head"><h2 class="section-title">数据与隐私</h2></div><div class="alert warning">当前为本地原型：没有真实登录或跨设备同步。资料只保存在当前浏览器，请不要输入完整门牌地址。正式版需要认证、访问控制和隐私政策。</div><div class="hrow" style="margin-top:14px">${btn('导出我的数据','export-data','secondary')}${btn('清除本地数据','clear-data','danger')}</div>`}
function renderModal(){const m=ui.modal;if(!m)return'';let content='';if(m.type==='recipe'){const f=ui.flow;const keys=[f?.base,f?.dish,f?.snack,...(f?.addons||[])].filter(Boolean);content=`<h2 class="title-lg">这顿怎么做？</h2><p class="lead">按顺序操作，食谱根据实际使用的商品包装调整。</p>${keys.map(k=>`<div class="sub-section"><div class="hrow" style="align-items:center"><span style="font-size:30px">${E[k].emoji}</span><div><h3 class="section-title">${E[k].zh}</h3><div class="bilingual">${E[k].en}</div></div></div>${E[k].instructions.map((ins,i)=>`<div class="instruction"><div class="step-num">${i+1}</div><div>${ins}</div></div>`).join('')}${E[k].tip?`<div class="alert warning">${E[k].tip}</div>`:''}</div>`).join('')}<div class="alert warning">过敏原、热量以及实际加热温度以商品包装及适用的食品安全指引为准。</div>`}
if(m.type==='adjust'){const k=m.key;const per=I[k].pantry;const have=totalQty(k);content=`<h2 class="title-lg">${I[k].zh} · ${I[k].en}</h2><p class="lead">${per?'常备调味品不逐次扣数量。用完了再点一次即可。':`系统估算还剩 ${qtyLabel(k,have)}，不用精确称重，快速选择就行。`}</p><div class="click-list">${per?`<button class="action-tile" data-action="empty-seasoning" data-key="${k}"><div class="action-title">已经用完了</div><span>→</span></button>`:[['half','大概只剩一半'],['quarter','大概只剩四分之一'],['empty','已经用完了']].map(([v,label])=>`<button class="action-tile" data-action="adjust-qty" data-key="${k}" data-value="${v}"><div class="action-title">${label}</div><span>→</span></button>`).join('')}</div>`}
if(m.type==='expiry'){const k=m.key;content=`<h2 class="title-lg">录入 ${I[k].zh} 的日期</h2><p class="lead">每批食材的有效期可能不同。请选择具体购买批次，按包装标签输入；不确定请留空。</p><div class="field" style="margin-bottom:14px"><span class="field-label">库存批次 / Batch</span><select id="expiry-batch">${state.pantry.filter(b=>b.ingredient===k&&(b.persistent?b.active!==false:b.remaining>0)).map(b=>`<option value="${b.id}">${b.purchased||'日期未记录'} · ${b.persistent?'常备品':qtyLabel(k,b.remaining)} ${b.expiry?'· 当前期限 '+b.expiry:''}</option>`).join('')}</select></div><div class="setting-grid"><label class="field"><span class="field-label">包装日期 / Date on pack</span><input type="date" id="expiry-date" /></label><label class="field"><span class="field-label">日期种类 / Date type</span><select id="expiry-type"><option value="useby">Use By / Expiry</option><option value="bestbefore">Best Before</option></select></label></div><div style="margin-top:18px">${btn('保存日期','save-expiry','primary',`data-key="${k}"`)}</div>`}
if(m.type==='add'){content=`<h2 class="title-lg">手动增加库存</h2><p class="lead">平时买菜直接从购物清单确认更方便。这里用于补录以前购买的食材。</p><div class="setting-grid"><label class="field"><span class="field-label">商品 / Item</span><select id="manual-ingredient">${Object.entries(I).map(([k,v])=>`<option value="${k}">${v.zh} / ${v.en}</option>`).join('')}</select></label><label class="field"><span class="field-label">买了几包 / Packs</span><input type="number" id="manual-packs" min="1" max="30" value="1" /></label></div><div style="margin-top:18px">${btn('添加到库存','save-manual')}</div><p class="tiny muted">每包数量使用当前演示商品包装规格。</p>`}
if(m.type==='checkslot'){const slot=m.slot;const plan=state.plans.find(p=>p.date===today()&&p.slot===slot);content=`<h2 class="title-lg">${slotLabel(slot)}吃了什么？</h2><p class="lead">Meal check-in · 不用强制自己做饭。</p><div class="click-list">${plan?`<button class="action-tile" data-action="log-plan-slot" data-slot="${slot}"><div><div class="action-title">🍚 吃了菜单里这顿</div><div class="action-description">${esc(mealName(plan))} · 自动扣库存</div></div><span>→</span></button>`:''}<button class="action-tile" data-action="log-quick" data-kind="outside" data-slot="${slot}"><div><div class="action-title">🍽 出去吃</div><div class="action-description">不扣厨房库存</div></div><span>→</span></button><button class="action-tile" data-action="log-quick" data-kind="delivery" data-slot="${slot}"><div><div class="action-title">🛵 点外卖</div><div class="action-description">不扣厨房库存</div></div><span>→</span></button><button class="action-tile" data-action="log-quick" data-kind="skipped" data-slot="${slot}"><div><div class="action-title">— 这顿没吃</div></div><span>→</span></button></div>`}
return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="Eat Lah 操作窗口"><div class="between" style="margin-bottom:13px"><span class="eyebrow" style="margin:0">EAT LAH</span><button class="mini-link" data-action="close-modal">✕ 关闭</button></div>${content}</div></div>`}
function render(){const page=state.profileCompleted?ui.page:'setup';let html;if(page==='setup')html=renderSetup();else if(page==='home')html=renderHome();else if(page==='choose')html=renderFlow();else if(page==='planner')html=renderPlanner();else if(page==='shopping')html=renderShopWithCooking();else if(page==='cook')html=renderCook();else if(page==='pantry')html=renderPantry();else if(page==='checkin')html=renderCheckin();else if(page==='profile')html=renderProfile();else html=renderHome();app.innerHTML=(page==='setup'?`<div style="max-width:100%;padding:35px 16px 80px">${html}</div>`:shell(html))+renderModal();if(page==='choose'&&ui.flow&&['base','dish','snack','lazyhome'].includes(ui.flow.step))enableSwipe()}
function saveToday(){const f=ui.flow;if(!f?.base)return flash('请先选择一顿饭。');const slot=f.slot||ui.checkSlot;const date=today();state.plans=state.plans.filter(p=>!(p.date===date&&p.slot===slot));const m={id:id(),date,slot,mood:f.mood,...recipeMeal(f)};state.plans.push(m);ui.activeMealId=m.id;save();flash('已生成这顿的购物清单。');navTo('shopping')}
function changeFlow(verb){const f=ui.flow;if(!f)return;const step=f.step;if(verb==='reject'){const k=activeCard();if(k)f.skips[step].push(k);render();return}if(verb==='back'){if(step==='effort')f.step='slot';else if(step==='mood')f.step='effort';else if(step==='base')f.step='mood';else if(step==='dish')f.step='base';else if(step==='snack')f.step=f.mode==='lazy'?'lazyhome':'dish';else if(step==='lazyhome')f.step='lazytype';else if(step==='lazytype')f.step='effort';else if(step==='summary')f.step=f.mode==='lazy'?'lazyhome':'snack';render();return}if(verb==='skip'){if(step==='base'){f.mode='lazy';f.step='lazyhome'}else if(step==='dish'){f.dish=null;f.step='snack'}else if(step==='snack'){f.snack=null;f.step='summary'}else if(step==='lazyhome'){f.step='lazytype'}render();return}if(verb==='accept'){const k=activeCard();if(!k)return changeFlow('skip');if(step==='base'){f.base=k;f.addons=[];f.step='dish'}else if(step==='dish'){f.dish=k;f.step='snack'}else if(step==='snack'){f.snack=k;f.step='summary'}else if(step==='lazyhome'){f.base=k;f.dish=null;f.snack=null;f.addons=[];f.step='summary'}render()}}
function enableSwipe(){const card=document.getElementById('swipe-card');if(!card)return;let x=null,y=null;card.addEventListener('pointerdown',e=>{x=e.clientX;y=e.clientY});card.addEventListener('pointerup',e=>{if(x==null)return;const dx=e.clientX-x,dy=e.clientY-y;x=null;y=null;if(Math.abs(dx)<75||Math.abs(dx)<Math.abs(dy)*1.25)return;changeFlow(dx>0?'accept':'reject')})}
function replacePlan(planId){const m=state.plans.find(p=>p.id===planId);if(!m)return;const bases=eligibleBases(false);if(!bases.length)return flash('没有符合厨具和过敏条件的选项。');const idx=bases.indexOf(m.baseId);m.baseId=bases[(idx+1+bases.length)%bases.length];m.dishId=null;m.snackId=null;save();render();flash('已更换这一顿，购物清单同步更新。')}
function storeProfileField(key,value){if(['budget','kcal'].includes(key)){const v=Number(value);if(!Number.isFinite(v)||v<0)return;state.profile[key]=v}else if(key==='postal'){state.profile[key]=String(value).replace(/[^0-9]/g,'').slice(0,6)}else state.profile[key]=String(value).slice(0,150);save()}
function quickAdd(k,packs){const p=C[k];if(!p)return;state.pantry.push({id:id(),ingredient:k,initial:p.pack*packs,remaining:p.pack*packs,persistent:Boolean(I[k].pantry),active:true,purchased:today(),expiry:null,dateType:'useby',storage:I[k].storage,source:'manual',isEstimate:false});state.purchaseHistory.push({id:id(),date:today(),ingredient:k,qty:p.pack*packs,packs,packSize:p.pack});save();flash(`${I[k].zh} 已添加到库存。`)}
function stockCorrection(k,mode){if(I[k].pantry){for(const b of state.pantry.filter(b=>b.ingredient===k&&b.persistent))b.active=false}else{const ratio=mode==='half'?.5:mode==='quarter'?.25:0;const target=Math.round(totalQty(k)*ratio);let sum=0;const active=state.pantry.filter(b=>b.ingredient===k&&!b.persistent).sort((a,b)=>(a.expiry||'9999').localeCompare(b.expiry||'9999'));for(const b of active){let n=Math.min(Math.max(0,target-sum),b.remaining);b.remaining=n;sum+=n}}state.transactions.push({id:id(),kind:'correction',ingredient:k,mode,date:new Date().toISOString()});ui.modal=null;save();render();flash('已更新库存估算。')}
function copyList(){const lines=shopLines();if(!lines.length)return flash('当前没有待购商品。');const text='Eat Lah — Shopping list\n'+lines.map(x=>`${I[x.k].en} (${I[x.k].zh}) — ${C[x.k].label} × ${ui.cartPacks[x.k]??x.packs}`).join('\n')+'\n\nExcuse me, where can I find these items?';if(navigator.clipboard?.writeText){navigator.clipboard.writeText(text).then(()=>flash('英文购物清单已复制。'),()=>legacyCopy(text))}else legacyCopy(text)}
function legacyCopy(text){const t=document.createElement('textarea');t.value=text;document.body.appendChild(t);t.select();try{document.execCommand('copy');flash('购物清单已复制。')}catch(e){flash('当前浏览器不支持复制。')}t.remove()}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='eat-lah-my-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
app.addEventListener('click',e=>{const target=e.target.closest('[data-nav],[data-action],[data-tool],[data-allergen],[data-set],[data-taste],[data-budget-preset],[data-kcal-preset],[data-setup-seasoning],[data-days],[data-pantry-filter]');if(!target)return;if(target.classList.contains('modal-backdrop')&&e.target!==target)return;
if(target.dataset.nav){navTo(target.dataset.nav);return}
if(target.dataset.tool){const k=target.dataset.tool;state.profile.tools=state.profile.tools.includes(k)?state.profile.tools.filter(x=>x!==k):[...state.profile.tools,k];save();render();return}
if(target.dataset.allergen){const k=target.dataset.allergen;state.profile.allergens=state.profile.allergens.includes(k)?state.profile.allergens.filter(x=>x!==k):[...state.profile.allergens,k];save();render();return}
if(target.dataset.taste){const k=target.dataset.taste;state.profile.tastes=state.profile.tastes.includes(k)?state.profile.tastes.filter(x=>x!==k):[...state.profile.tastes,k];save();render();return}
if(target.dataset.set){state.profile[target.dataset.set]=target.dataset.value;save();render();return}
if(target.dataset.budgetPreset!==undefined){state.profile.budget=Number(target.dataset.budgetPreset);save();render();return}
 if(target.dataset.kcalPreset!==undefined){state.profile.kcal=Number(target.dataset.kcalPreset);save();render();return}
 if(target.dataset.setupSeasoning){const k=target.dataset.setupSeasoning;ui.setupSeasonings=ui.setupSeasonings.includes(k)?ui.setupSeasonings.filter(x=>x!==k):[...ui.setupSeasonings,k];render();return}
if(target.dataset.days){ui.planDays=Number(target.dataset.days);render();return}
if(target.dataset.pantryFilter){ui.pantryFilter=target.dataset.pantryFilter;render();return}
const action=target.dataset.action, k=target.dataset.key;
if(action==='choose-slot'){begin('cook',target.dataset.slot);return}
else if(action==='choose-effort'){ui.flow.mode=target.dataset.value==='lazy'?'lazy':'cook';ui.flow.step=ui.flow.mode==='lazy'?'lazytype':'mood';render();return}
 else if(action==='choose-mood'){ui.flow.mood=target.dataset.value;if(ui.flow.mood==='surprise'){const list=eligibleBases(false);const pick=list[0];if(!pick){flash('没有符合条件的选项。');return}ui.flow.base=pick;ui.flow.dish=null;ui.flow.snack=null;ui.flow.step='summary'}else ui.flow.step='base';render();return}
else if(action==='go-lazy'){ui.flow.mode='lazy';ui.flow.step='lazytype';render();return}
else if(action==='toggle-addon'){const f=ui.flow,k=target.dataset.key;f.addons=f.addons.includes(k)?f.addons.filter(x=>x!==k):[...f.addons,k];render();return}
else if(action==='start-cooking'){navTo('cook');return}
else if(action==='finish-cooking'){const m=currentCookingMeal();if(m&&recordMeal(m,m.slot,m.date)){flash('这一顿已完成：打卡与库存同步更新。');navTo('checkin')}return}
else if(action==='setup-next'){if(ui.onboardStep<3){ui.onboardStep++;render()}else{for(const k of ui.setupSeasonings)if(!pantryOwned(k))quickAdd(k,1);state.profileCompleted=true;save();navTo('home');flash('欢迎来到 Eat Lah！')}}
else if(action==='setup-back'){ui.onboardStep=Math.max(0,ui.onboardStep-1);render()}
else if(action==='start-cook')begin('cook');else if(action==='start-lazy')begin('lazy');else if(action==='start-surprise'){begin('cook')}
else if(action==='lazy-home'){ui.flow.step='lazyhome';render()}else if(action==='lazy-out'||action==='lazy-delivery'){ui.flow.lazyPlace=action==='lazy-out'?'outside':'delivery';ui.flow.step='lazyexternal';render()}
else if(action==='flow-accept')changeFlow('accept');else if(action==='flow-reject')changeFlow('reject');else if(action==='flow-skip')changeFlow('skip');else if(action==='flow-back')changeFlow('back');
else if(action==='log-external'){const kind=ui.flow.lazyPlace==='outside'?'outside':'delivery';if(recordMeal({kind},target.dataset.slot)){flash('已打卡，这顿不扣家里库存。');navTo('checkin')}}
else if(action==='select-slot'){ui.checkSlot=target.dataset.slot;render()}
else if(action==='save-meal')saveToday();else if(action==='recipe-modal'){ui.modal={type:'recipe'};render()}
else if(action==='generate-plan'){if(state.plans.length&&!confirm('重新生成菜单会覆盖现有计划（不会删除打卡历史）。确定吗？'))return;generatePlan()}
else if(action==='swap-plan')replacePlan(target.dataset.id);else if(action==='eat-plan'){const m=state.plans.find(x=>x.id===target.dataset.id);if(m&&recordMeal(m,m.slot,m.date)){flash('吃好了！已自动打卡并扣减库存。');render()}}
else if(action==='open-shopping')navTo('shopping');else if(action==='open-pantry')navTo('pantry');else if(action==='open-checkin')navTo('checkin');else if(action==='open-home')navTo('home');else if(action==='open-planner')navTo('planner');else if(action==='open-choose')navTo('choose');
else if(action==='toggle-receipt'){ui.receipt=!ui.receipt;render()}else if(action==='copy-shopping')copyList();
else if(action==='cart-check'){ui.cartCheck[k]=ui.cartCheck[k]===false?true:false;render()}
else if(action==='pack-minus'){const current=ui.cartPacks[k]??shopLines().find(x=>x.k===k)?.packs??1;ui.cartPacks[k]=Math.max(0,current-1);render()}
else if(action==='pack-plus'){const current=ui.cartPacks[k]??shopLines().find(x=>x.k===k)?.packs??1;ui.cartPacks[k]=current+1;render()}
else if(action==='confirm-shopping')buyShopping();else if(action==='pantry-adjust'){ui.modal={type:'adjust',key:k};render()}else if(action==='pantry-expiry'){ui.modal={type:'expiry',key:k};render()}else if(action==='add-pantry'){ui.modal={type:'add'};render()}
else if(action==='adjust-qty'){stockCorrection(k,target.dataset.value)}else if(action==='empty-seasoning'){stockCorrection(k,'empty')}
else if(action==='save-expiry'){const date=document.getElementById('expiry-date')?.value;const type=document.getElementById('expiry-type')?.value;if(!date)return flash('请选择包装上真实的有效期日期。');const selectedBatch=document.getElementById('expiry-batch')?.value;const b=state.pantry.find(b=>b.id===selectedBatch&&b.ingredient===k);if(!b)return flash('请先选择一个库存批次。');b.expiry=date;b.dateType=type;ui.modal=null;save();render();flash('已保存有效期。')}
else if(action==='save-manual'){const ing=document.getElementById('manual-ingredient')?.value;const packs=Math.max(1,Math.min(30,Number(document.getElementById('manual-packs')?.value)||1));if(ing&&C[ing]){quickAdd(ing,packs);ui.modal=null;render()}}
else if(action==='check-slot'){ui.modal={type:'checkslot',slot:target.dataset.slot};render()}
else if(action==='log-plan-slot'){const slot=target.dataset.slot;const m=state.plans.find(p=>p.date===today()&&p.slot===slot);if(m&&recordMeal(m,slot)){ui.modal=null;render();flash('已打卡，库存自动更新。')}}
else if(action==='log-quick'){const slot=target.dataset.slot;const kind=target.dataset.kind;if(recordMeal({kind},slot)){ui.modal=null;render();flash('已打卡，不会扣家中食材。')}}
else if(action==='undo-log')undoLog(target.dataset.id);else if(action==='close-modal'){ui.modal=null;render()}
else if(action==='export-data')exportData();else if(action==='clear-data'){if(confirm('确定清除这个浏览器里 Eat Lah 的全部数据吗？该操作不能撤销。')){localStorage.removeItem(STORE);state=defaultState();ui.page='setup';ui.onboardStep=0;ui.flow=null;ui.setupSeasonings=[];render()}}
});
app.addEventListener('change',e=>{const key=e.target.dataset.profile;if(key){storeProfileField(key,e.target.value);if(key==='postal')e.target.value=state.profile.postal}});
render();
window.EATLAH_TEST={getState:()=>JSON.parse(JSON.stringify(state)),getShopping:()=>shopLines(),getCandidates:()=>eligibleBases(false),today,reset:()=>{localStorage.removeItem(STORE);location.reload()}};
})();
